def merge_sorted_lists():
    list1 = list(map(float, input().split()))
    list2 = list(map(float, input().split()))
    merged = []
    i, j = 0, 0

    while i < len(list1) and j < len(list2):
        if list1[i] <= list2[j]:
            merged.append(list1[i])
            i += 1
        else:
            merged.append(list2[j])
            j += 1

