def is_valid_sudoku(grid):
    def is_valid_unit(unit):
        nums = [num for num in unit if num != 0]
        return len(nums) == len(set(nums))

    def get_box(row, col):
        return (row // 3) * 3 + (col // 3)

    rows = grid
    cols = [[grid[row][col] for row in range(9)] for col in range(9)]
    boxes = [[] for _ in range(9)]
    for row in range(9):
        for col in range(9):
            boxes[get_box(row, col)].append(grid[row][col])

    for unit in rows + cols + boxes:
        if not is_valid_unit(unit):
            return False

    return True
```

